const WALLET_COLORS=[['Grafito','#36383a'],['Bosque','#245640'],['Azul tinta','#294b6b'],['Arena','#d9c29f'],['Rosa','#d5a0ad'],['Lila','#b39acb'],['Coral','#df987b'],['Marfil','#eee5d0']];
const WALLET_PATTERNS={plain:'Liso',stripes:'Rayas',checker:'Damero',waves:'Ondas',dots:'Puntos',facets:'Geometría',circuit:'Circuito',aurora:'Degradado',grid:'Cuadrícula',chevron:'Zigzag',herringbone:'Espiga',honeycomb:'Panal',scales:'Escamas',terrazzo:'Terrazo',sunburst:'Rayos',plaid:'Tartán',rings:'Anillos',topography:'Topografía',diamonds:'Rombos',dashes:'Trazos'};
const WALLET_DEFAULT={background:'#245640',accent:'#eae0c7',brandColor:'#f5f0e5',brandAuto:true,pattern:'plain'};
let walletDraft={...WALLET_DEFAULT},walletSourcePromise,walletFrame;
const WALLET_BASE_IMAGE='data:image/webp;base64,';
function restoreWalletDraft(raw){
 const hex=value=>typeof value==='string'&&/^#[0-9a-f]{6}$/i.test(value);
 walletDraft={background:hex(raw?.background)?raw.background:WALLET_DEFAULT.background,accent:hex(raw?.accent)?raw.accent:WALLET_DEFAULT.accent,brandColor:hex(raw?.brandColor)?raw.brandColor:WALLET_DEFAULT.brandColor,brandAuto:raw?.brandAuto!==false,pattern:Object.hasOwn(WALLET_PATTERNS,raw?.pattern)?raw.pattern:'plain'};
 if(document.querySelector('#wallet-form'))setupWalletEditor();
}
function personalizationTabs(active){return `<nav class="personalization-tabs" aria-label="Qué quieres personalizar"><a href="#/personalizacion" ${active==='stickers'?'aria-current="page"':''}>Stickers</a><a href="#/personalizacion/carteras" ${active==='wallets'?'aria-current="page"':''}>Carteras magnéticas</a></nav>`;}
function walletPersonalization(){
 return `<section class="page-heading"><h1>Personalización</h1><p>Tu color. Tu patrón. Tu Power Case.</p></section>${personalizationTabs('wallets')}<section class="wallet-editor" id="wallet-editor"><div class="wallet-preview"><span class="eyebrow">VISTA PREVIA DE TU DISEÑO</span><canvas id="wallet-canvas" width="720" height="720" role="img" aria-label="Vista previa de tu cartera personalizada"></canvas><p class="note">Prueba de diseño sobre la cartera Power Case.</p><p id="wallet-render-status" role="status" aria-live="polite"></p></div><form id="wallet-form"><span class="eyebrow">CARTERA MAGNÉTICA</span><h2>Crea tu combinación.</h2><p class="accessory-price">${personalizedWalletPrice()}</p><p class="note">Precio base ${mxn(ACCESSORY_CATEGORIES.carteras.price)} + ${mxn(PERSONALIZATION_FEE)} de personalización. Guardar el diseño es gratis.</p><p>Combina el color de la cartera con un patrón. La firma Power Case se conserva en tu diseño.</p><fieldset><legend>Color de la cartera</legend><div class="wallet-palette">${WALLET_COLORS.map(([name,color])=>`<button type="button" data-wallet-color="${color}" title="${name}" aria-label="Color ${name}" aria-pressed="${walletDraft.background.toLowerCase()===color}" style="--wallet-color:${color}"><span aria-hidden="true"></span></button>`).join('')}</div><label class="wallet-color-field">Elige otro color<input type="color" name="background" value="${walletDraft.background}"></label></fieldset><fieldset><legend>Patrón</legend><div class="wallet-patterns">${Object.entries(WALLET_PATTERNS).map(([id,name])=>`<button type="button" data-wallet-pattern="${id}" aria-pressed="${walletDraft.pattern===id}"><span class="wallet-pattern-icon wallet-pattern-${id}" aria-hidden="true"></span>${name}</button>`).join('')}</div></fieldset><label class="wallet-color-field">Color del patrón<input type="color" name="accent" value="${walletDraft.accent}"></label><fieldset class="wallet-brand-controls"><legend>Firma POWER CASE</legend><label class="wallet-color-field">Color de la firma<input type="color" name="brandColor" value="${walletDraft.brandColor}"></label><label class="wallet-brand-auto"><input type="checkbox" name="brandAuto" ${walletDraft.brandAuto?'checked':''}> Ajustar contraste automáticamente</label></fieldset><div class="wallet-editor-actions"><button type="button" class="button dark" data-wallet-download>Guardar diseño</button><button type="button" class="text-link" data-wallet-reset>Restablecer</button></div><p class="note">Guarda tu diseño en favoritos y añádelo a la bolsa cuando quieras.</p></form></section>`;
}
async function walletSource(){
 walletSourcePromise??=new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=canvas.height=720;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,720,720);resolve(context.getImageData(0,0,720,720));};image.onerror=()=>reject(Error('No se pudo cargar la cartera.'));image.src=WALLET_BASE_IMAGE;}).catch(error=>{walletSourcePromise=null;throw error;});
 return walletSourcePromise;
}
function walletPattern(context,background,accent,pattern,size){
 context.fillStyle=background;context.fillRect(0,0,size,size);context.fillStyle=accent;context.strokeStyle=accent;context.lineWidth=3;
 if(pattern==='stripes'){for(let x=-size;x<size*2;x+=70){context.beginPath();context.moveTo(x,0);context.lineTo(x+size,size);context.lineTo(x+size+28,size);context.lineTo(x+28,0);context.fill();}}
 if(pattern==='checker'){for(let y=0;y<size;y+=66)for(let x=0;x<size;x+=66)if((x/66+y/66)%2===0)context.fillRect(x,y,66,66);}
 if(pattern==='dots'){for(let y=20;y<size;y+=58)for(let x=20;x<size;x+=58){context.beginPath();context.arc(x+(Math.round(y/58)%2)*20,y,8,0,Math.PI*2);context.fill();}}
 if(pattern==='waves'){for(let y=-80;y<size+80;y+=90){context.beginPath();for(let x=0;x<=size;x+=4){const py=y+Math.sin(x/42)*28;x?context.lineTo(x,py):context.moveTo(x,py);}for(let x=size;x>=0;x-=4)context.lineTo(x,y+40+Math.sin(x/42)*28);context.closePath();context.fill();}}
 if(pattern==='facets'){for(let y=0;y<size;y+=140)for(let x=0;x<size;x+=150){context.beginPath();context.moveTo(x,y);context.lineTo(x+150,y+140);context.lineTo(x,y+140);context.closePath();context.fill();}}
 if(pattern==='circuit'){for(let x=30;x<size;x+=85){context.beginPath();context.moveTo(x,0);context.lineTo(x,size*.3);context.lineTo(x+35,size*.3+40);context.lineTo(x+35,size*.7);context.stroke();context.beginPath();context.arc(x+35,size*.7,7,0,Math.PI*2);context.stroke();context.beginPath();context.moveTo(x,size);context.lineTo(x,size*.8);context.lineTo(x-25,size*.75);context.stroke();}}
 if(pattern==='aurora'){const gradient=context.createLinearGradient(0,0,size,size);gradient.addColorStop(0,background);gradient.addColorStop(1,accent);context.fillStyle=gradient;context.fillRect(0,0,size,size);}
 if(pattern==='grid'){for(let x=0;x<size;x+=48){context.beginPath();context.moveTo(x,0);context.lineTo(x,size);context.stroke();}for(let y=0;y<size;y+=48){context.beginPath();context.moveTo(0,y);context.lineTo(size,y);context.stroke();}}
 if(pattern==='chevron'){context.lineWidth=18;for(let y=-80;y<size+80;y+=66){context.beginPath();for(let x=0;x<=size;x+=40){const py=y+(Math.round(x/40)%2)*26;x?context.lineTo(x,py):context.moveTo(x,py);}context.stroke();}}
 if(pattern==='herringbone'){context.lineWidth=13;for(let y=-40;y<size+40;y+=42)for(let x=0;x<size;x+=70){context.beginPath();context.moveTo(x,y);context.lineTo(x+35,y+30);context.lineTo(x+70,y);context.stroke();}}
 if(pattern==='honeycomb'){context.lineWidth=3;for(let y=0;y<size+40;y+=52)for(let x=-40;x<size+40;x+=60){const cx=x+(Math.round(y/52)%2)*30;context.beginPath();for(let i=0;i<6;i++){const angle=(i*60+30)*Math.PI/180,px=cx+30*Math.cos(angle),py=y+30*Math.sin(angle);i?context.lineTo(px,py):context.moveTo(px,py);}context.closePath();context.stroke();}}
 if(pattern==='scales'){context.lineWidth=5;for(let y=-20;y<size+30;y+=32)for(let x=-40;x<size+40;x+=64){context.beginPath();context.arc(x+(Math.round(y/32)%2)*32,y,32,0,Math.PI);context.stroke();}}
 if(pattern==='terrazzo'){let seed=947;const random=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);for(let i=0;i<260;i++){const x=random()*size,y=random()*size,r=6+random()*13;context.globalAlpha=.5+random()*.5;context.beginPath();context.moveTo(x-r,y);context.lineTo(x+r*.7,y-r*.8);context.lineTo(x+r,y+r*.5);context.lineTo(x-r*.3,y+r);context.closePath();context.fill();}context.globalAlpha=1;}
 if(pattern==='sunburst'){const cx=size*.64,cy=size*.35;for(let i=0;i<24;i+=2){context.beginPath();context.moveTo(cx,cy);context.arc(cx,cy,size*2,i*Math.PI/12,(i+1)*Math.PI/12);context.closePath();context.fill();}}
 if(pattern==='plaid'){for(let x=0;x<size;x+=100){context.globalAlpha=.5;context.fillRect(x,0,26,size);context.globalAlpha=1;context.fillRect(x+38,0,3,size);}for(let y=0;y<size;y+=100){context.globalAlpha=.5;context.fillRect(0,y,size,26);context.globalAlpha=1;context.fillRect(0,y+38,size,3);}}
 if(pattern==='rings'){context.lineWidth=6;for(let radius=15;radius<size*1.2;radius+=24){context.beginPath();context.arc(size*.35,size*.48,radius,0,Math.PI*2);context.stroke();}}
 if(pattern==='topography'){context.lineWidth=2.5;for(let ring=1;ring<32;ring++){context.beginPath();for(let a=0;a<=Math.PI*2+.05;a+=.04){const r=ring*17*(1+.14*Math.sin(a*3)+.08*Math.cos(a*5)),x=size*.55+Math.cos(a)*r,y=size*.52+Math.sin(a)*r*.8;a?context.lineTo(x,y):context.moveTo(x,y);}context.closePath();context.stroke();}}
 if(pattern==='diamonds'){for(let y=-60;y<size+60;y+=85)for(let x=-60;x<size+60;x+=85){context.beginPath();context.moveTo(x,y-27);context.lineTo(x+23,y);context.lineTo(x,y+27);context.lineTo(x-23,y);context.closePath();context.fill();}}
 if(pattern==='dashes'){context.lineWidth=7;context.lineCap='round';for(let y=20;y<size;y+=52)for(let x=10;x<size;x+=57){const shift=(Math.round(y/52)%2)*22;context.beginPath();context.moveTo(x+shift,y);context.lineTo(x+shift+18,y+18);context.stroke();}context.lineCap='butt';}
}
async function drawWallet(canvas=document.querySelector('#wallet-canvas'),savedDraft=null){
 if(!canvas)return;
 try{
  const source=await walletSource();if(!canvas.isConnected)return;
  const draft={...(savedDraft||walletDraft)},size=720,patternCanvas=document.createElement('canvas');patternCanvas.width=patternCanvas.height=size;const patternContext=patternCanvas.getContext('2d',{willReadFrequently:true});walletPattern(patternContext,draft.background,draft.accent,draft.pattern,size);const pattern=patternContext.getImageData(0,0,size,size).data;
  const result=new ImageData(new Uint8ClampedArray(source.data),size,size),color=draft.background.match(/[a-f0-9]{2}/gi).map(v=>parseInt(v,16));
  for(let y=0;y<size;y++)for(let x=0;x<size;x++){
   const offset=(y*size+x)*4;
   let r=source.data[offset],g=source.data[offset+1],b=source.data[offset+2];
   if(x>size*.34&&x<size*.67&&y>size*.775&&y<size*.837){
    const sample=((y-28)*size+x)*4,edge=Math.min(x-size*.34,size*.67-x,y-size*.775,size*.837-y),blend=Math.min(1,edge/4);
    r=r*(1-blend)+source.data[sample]*blend;g=g*(1-blend)+source.data[sample+1]*blend;b=b*(1-blend)+source.data[sample+2]*blend;
   }
   const light=.2126*r+.7152*g+.0722*b;
   const nx=x/size,ny=y/size,edgeX=Math.max(.239,Math.min(.761,nx)),edgeY=Math.max(.09,Math.min(.87,ny));
   if(nx<.199||nx>.801||ny<.05||ny>.91||(nx-edgeX)**2+(ny-edgeY)**2>.04**2||light>195)continue;
   const amount=Math.min(1,(195-light)/30),shade=Math.min(1.13,.25+light/120),front=y/size>.153+.065*Math.sin(Math.PI*Math.max(0,Math.min(1,(x/size-.20)/.60)));
   const panel=x>size*.215&&x<size*.785&&y<size*.899&&front;
   for(let c=0;c<3;c++){const tint=(panel?pattern[offset+c]:color[c])*shade;result.data[offset+c]=source.data[offset+c]*(1-amount)+tint*amount;}
  }
  const context=canvas.getContext('2d');context.putImageData(result,0,0);paintWalletBrand(context,result,draft,size,canvas,!savedDraft);canvas.setAttribute('aria-label',`Cartera Power Case personalizada: ${WALLET_PATTERNS[draft.pattern]}`);if(!savedDraft)document.querySelector('#wallet-render-status').textContent='';
 }catch(error){if(!savedDraft&&canvas.isConnected)document.querySelector('#wallet-render-status').textContent='No se pudo generar la vista previa. Intenta abrir de nuevo esta sección.';}
}
function paintWalletBrand(context,image,draft,size,canvas,editor){
 let light=0,samples=0;
 for(let y=Math.round(size*.79);y<size*.83;y+=2)for(let x=Math.round(size*.37);x<size*.64;x+=2){const i=(y*size+x)*4;light+=.2126*image.data[i]+.7152*image.data[i+1]+.0722*image.data[i+2];samples++;}
 const color=draft.brandAuto?(light/samples>145?'#161616':'#faf7f0'):draft.brandColor;
 context.save();context.font='500 14px Arial, sans-serif';context.textBaseline='alphabetic';context.fillStyle=color;
 const text='POWER CASE',spacing=2.6,width=[...text].reduce((sum,letter)=>sum+context.measureText(letter).width,0)+spacing*(text.length-1);
 let x=(size-width)/2;context.shadowColor=color==='#161616'?'#ffffff30':'#00000024';context.shadowOffsetY=.5;context.shadowBlur=.4;
 for(const letter of text){context.fillText(letter,x,size*.818);x+=context.measureText(letter).width+spacing;}context.restore();
 if(canvas)canvas.dataset.brandColor=color;
 const picker=document.querySelector('#wallet-form input[name=brandColor]');if(editor&&draft.brandAuto&&picker)picker.value=color;
}
function setupWalletEditor(){
 const form=document.querySelector('#wallet-form');if(!form)return;
 form.elements.background.value=walletDraft.background;form.elements.accent.value=walletDraft.accent;form.elements.brandColor.value=walletDraft.brandColor;form.elements.brandAuto.checked=walletDraft.brandAuto;form.elements.accent.disabled=walletDraft.pattern==='plain';
 for(const button of form.querySelectorAll('[data-wallet-color]'))button.setAttribute('aria-pressed',button.dataset.walletColor===walletDraft.background.toLowerCase());
 for(const button of form.querySelectorAll('[data-wallet-pattern]'))button.setAttribute('aria-pressed',button.dataset.walletPattern===walletDraft.pattern);
 form.style.setProperty('--wallet-background',walletDraft.background);form.style.setProperty('--wallet-accent',walletDraft.accent);
 cancelAnimationFrame(walletFrame);walletFrame=requestAnimationFrame(()=>drawWallet());
}
document.addEventListener('input',event=>{
 if(!event.target.closest('#wallet-form')||!['background','accent','brandColor','brandAuto'].includes(event.target.name))return;
 walletDraft={...walletDraft,[event.target.name]:event.target.type==='checkbox'?event.target.checked:event.target.value,...(event.target.name==='brandColor'?{brandAuto:false}:{})};setupWalletEditor();workspace?.changed();
});
document.addEventListener('click',async event=>{
 const palette=event.target.closest('[data-wallet-color]'),pattern=event.target.closest('[data-wallet-pattern]'),reset=event.target.closest('[data-wallet-reset]');
 if(palette||pattern||reset){walletDraft=reset?{...WALLET_DEFAULT}:{...walletDraft,...(palette?{background:palette.dataset.walletColor}:{pattern:pattern.dataset.walletPattern})};setupWalletEditor();workspace?.changed();}
 const download=event.target.closest('[data-wallet-download]');if(!download)return;
 if(!session&&accountInitializing)await accountInitialization;
 if(!session){account();return;}
 if(!workspace?.ready){toast('Espera a que termine de cargar tu cuenta.');return;}
 download.disabled=true;
 try{
  const draft={...walletDraft};
  if(!savedWallets.some(item=>JSON.stringify(item.draft)===JSON.stringify(draft)))savedWallets.push({id:'wallet-'+crypto.randomUUID(),draft});
  workspace.changed();refreshFavorites();toast('Diseño añadido a tus favoritos.');
 }catch{toast('No se pudo guardar el diseño. Inténtalo de nuevo.');}finally{download.disabled=false;}

});

let savedWallets=[];
function normalizeWalletDesign(raw){
 if(!raw||raw.kind==='pop'||!/^wallet-[a-f0-9-]{36}$/.test(raw.id)||!raw.draft)return null;
 const previous=walletDraft;restoreWalletDraft(raw.draft);const draft={...walletDraft};walletDraft=previous;return {id:raw.id,draft};
}
function walletDesignPreview(item){
 const token=encodeURIComponent(JSON.stringify(item.draft));
 queueMicrotask(renderSavedWallets);
 return `<canvas width="720" height="720" data-wallet-preview="${safe(token)}" role="img" aria-label="Cartera personalizada: ${safe(WALLET_PATTERNS[item.draft.pattern])}"></canvas>`;
}
function renderSavedWallets(){
 document.querySelectorAll('[data-wallet-preview]:not([data-painted])').forEach(canvas=>{canvas.dataset.painted='true';drawWallet(canvas,JSON.parse(decodeURIComponent(canvas.dataset.walletPreview)));});
}
function savedWalletCard(item){return `<article class="accessory-card">${walletDesignPreview(item)}<button type="button" class="favorite-toggle favorite-card" data-delete-wallet="${item.id}" aria-pressed="true" aria-label="Quitar cartera personalizada de favoritos" title="Quitar de favoritos">${favoriteHeart()}</button><div class="accessory-card-copy"><span class="accessory-category">Cartera magnética personalizada</span><h3>${safe(WALLET_PATTERNS[item.draft.pattern])}</h3><p>${personalizedWalletPrice()}</p><p class="note">Incluye ${mxn(PERSONALIZATION_FEE)} de personalización.</p><button type="button" class="button dark full" data-add-wallet="${item.id}">Añadir a la bolsa</button><button type="button" class="text-link" data-edit-wallet="${item.id}">Abrir diseño</button></div></article>`;}
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-add-wallet],[data-edit-wallet],[data-delete-wallet]');if(!button||!session)return;
 const item=savedWallets.find(item=>item.id===(button.dataset.addWallet||button.dataset.editWallet||button.dataset.deleteWallet));if(!item)return;
 if(button.hasAttribute('data-add-wallet'))add({wallet:structuredClone(item)});
 if(button.hasAttribute('data-edit-wallet')){walletDraft={...item.draft};location.hash='/personalizacion/carteras';if(document.querySelector('#wallet-form'))setupWalletEditor();workspace?.changed();}
 if(button.hasAttribute('data-delete-wallet')){savedWallets=savedWallets.filter(value=>value.id!==item.id);workspace?.changed();refreshFavorites();}
});
